const fs=require('fs'),path=require('path'),crypto=require('crypto');
const W=path.dirname(__dirname),root=W,source=path.join(root,'source/MagVarUpdate');
const lexer=require(path.join(source,'node_modules/es-module-lexer'));
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const modules=new Map(),pending=new Set();const directory=path.join(root,'runtime/modules');fs.mkdirSync(directory,{recursive:true});
function dependencies(code,base){return lexer.parse(code)[0].filter(x=>x.n&&!x.n.startsWith('node:')).map(x=>({...x,url:new URL(x.n,base).href}));}
async function get(url){const cached=path.join(W,'runtime-downloads',hash(url)+'.json');if(fs.existsSync(cached))return JSON.parse(fs.readFileSync(cached));let failure;for(let i=0;i<3;i++){try{const r=await fetch(url,{signal:AbortSignal.timeout(45000)});if(!r.ok)throw Error(r.status+' '+url);const code=await r.text();if(!/javascript|ecmascript/.test(r.headers.get('content-type')||''))throw Error('Not JS '+url);const result={url,code,contentType:r.headers.get('content-type'),sha256:hash(code),bytes:Buffer.byteLength(code)};fs.mkdirSync(path.dirname(cached),{recursive:true});fs.writeFileSync(cached,JSON.stringify(result));return result;}catch(e){failure=e;}}throw failure;}
(async()=>{await lexer.init;const entry=fs.readFileSync(path.join(source,'artifact/bundle.js'),'utf8');dependencies(entry,'https://example.invalid/').forEach(x=>pending.add(x.url));while(pending.size){const batch=[...pending].slice(0,8);batch.forEach(u=>pending.delete(u));const results=await Promise.all(batch.map(get));for(const m of results){modules.set(m.url,m);for(const d of dependencies(m.code,m.url))if(!modules.has(d.url))pending.add(d.url);}console.log(JSON.stringify({downloaded:modules.size,pending:pending.size}));}
const name=u=>hash(u).slice(0,24)+'.js';
function rewrite(code,base,entry=false){for(const d of dependencies(code,base).reverse()){const value=entry?'./modules/'+name(d.url):'./'+name(d.url);code=code.slice(0,d.s)+(d.d>=0?JSON.stringify(value):value)+code.slice(d.e);}return code.replace(/\/\/# sourceMappingURL=.*$/gm,'');}
const manifest=[];for(const m of modules.values()){const code=rewrite(m.code,m.url);fs.writeFileSync(path.join(directory,name(m.url)),code);manifest.push({upstream:m.url,upstreamSha256:m.sha256,file:'runtime/modules/'+name(m.url),sha256:hash(code),bytes:Buffer.byteLength(code)});}
const bundled=rewrite(entry,'https://example.invalid/',true);fs.writeFileSync(path.join(root,'runtime/bundle.js'),bundled);fs.copyFileSync(path.join(source,'artifact/bundle.js.LICENSE.txt'),path.join(root,'runtime/bundle.js.LICENSE.txt'));
fs.writeFileSync(path.join(root,'DEPENDENCIES.json'),JSON.stringify({upstreamCommit:'d03b7dc8a6ebf9bd611c7e2dc91f3b35462deebc',modules:manifest.sort((a,b)=>a.upstream.localeCompare(b.upstream)),entry:{file:'runtime/bundle.js',sha256:hash(bundled),bytes:Buffer.byteLength(bundled)}},null,2)+'\n');console.log(JSON.stringify({pass:true,modules:modules.size,entryBytes:Buffer.byteLength(bundled)}));})().catch(e=>{console.error(e);process.exit(1)});
